		define('EDD_PLUGIN_DIR', plugin_dir_path(EDD_PLUGIN_FILE));
	}
	if (!defined('EDD_PLUGIN_URL')) {
		define('EDD_PLUGIN_URL', plugins_url('/', EDD_PLUGIN_FILE));
	}
